/* Nonproduction click-through simulation; no network requests or provider integrations. */
const {screens,bodies,helpers}=FLOCKLETTER;
const {esc,go,action,note,field,select,emailPreview}=helpers;
const root=document.getElementById('root'),dialog=document.getElementById('review-dialog');
let current=screens.find(s=>s.slug==='dashboard'),plan=2,toastTimer,sampleCopy='',sampleWorkspace='Alpine Paper Co.',sampleAuthNext='workspace-onboarding';
const planNames={1:'Tier 1 · $15 / month',2:'Tier 2 · $25 / month',3:'Tier 3 · $39 / month'};
const primary={dashboard:['+ Create campaign','templates'],contacts:['+ Import contacts','import-mapping'],campaigns:['+ Create campaign','templates'],companies:['+ Add a brand','brand-settings'],templates:['Your campaigns','campaigns'],media:['Back to editor','campaign-editor'],reports:['All campaigns','campaigns'],activity:['Back to dashboard','dashboard']};
const variants={dashboard:['Empty workspace','Sending held'],contacts:['Empty audience'],campaigns:['Empty campaigns','Read-only'],provisioning:['Setup failed'],'import-review':['Quota exceeded'],'sender-dns':['Verified'],preflight:['Blocked'],'send-progress':['Paused','Uncertain outcome'],team:['Seat limit'],billing:['Complimentary'],unsubscribe:['Save failed']};
function currentSlug(){return location.hash.replace(/^#/,'').split('?')[0]||'dashboard'}
function route(slug){location.hash=slug}
function nav(active,operator=false){const links=operator?[['Overview','platform'],['Workspaces','platform-workspace'],['Delivery & capacity','platform-health'],['Support','support-review']]:[['Overview','dashboard'],['Campaigns','campaigns'],['Audience','contacts'],['Reports','reports'],['Settings','billing']];return `<nav class='nav' aria-label='Main navigation'>${links.map(([l,s])=>`<a href='#${s}' ${active===s?`class='active' aria-current='page'`:''}>${l}</a>`).join('')}</nav>`}
const softwareLogo=()=>`<img class='software-logo' src='assets/frosty-flamingo-software.png' alt='Frosty Flamingo Software logo' width='1475' height='1067'>`;
function header(s){if(s.group==='Subscriber')return `<div class='prototype-note'><strong>INTERACTIVE DESIGN PREVIEW</strong><span>· Fictional reader flow · No emails are sent</span></div><header class='subscriber-header' aria-label='Software provider'>${softwareLogo()}</header>`;const publicView=['Discover','Account','Subscriber'].includes(s.group),ops=s.group==='Operations';let active=s.slug;if(s.group==='Campaigns'&&active!=='reports')active='campaigns';if(s.group==='Audience')active='contacts';if(s.group==='Settings')active='billing';return `<div class='prototype-note'><strong>INTERACTIVE DESIGN PREVIEW</strong><span>· Fictional sample data · No live signups, payments or emails</span></div><header class='header'><a class='brand' href='#home' aria-label='Flockletter home'><span class='brandmark' aria-hidden='true'>f</span>flockletter</a>${publicView?`<nav class='nav' aria-label='Product navigation'><a href='#home'>Why Flockletter</a><a href='#pricing'>Pricing</a><a href='#support'>Help</a></nav>`:nav(active,ops)}<div class='header-right'>${publicView?`${go('Sign in','signin','quiet')}${go('View plans →','pricing')}`:ops?`<span class='badge red'>Platform operator</span><a class='avatar' href='#account-security' aria-label='Operator account'>OP</a>`:`<a href='#workspaces' class='workspace'><span>WORKSPACE</span>${esc(sampleWorkspace)} &nbsp;⌄</a><a class='avatar' href='#account-security' aria-label='Your account'>AM</a>`}</div>${softwareLogo()}</header>`}
function render(){current=screens.find(s=>s.slug===currentSlug());if(!current){root.innerHTML=`${header(screens[0])}<main class='main'><h1>This screen is not in the review.</h1>${go('Open dashboard','dashboard')}</main>`;return}const s=current,i=screens.indexOf(s),noHead=['home','signup','signin','verify-recover','invitation','subscribe','confirmation','preferences','unsubscribe','expired-link','access-consent','access-help'].includes(s.slug);document.title=`${s.id} · ${s.title} — Flockletter review`;root.innerHTML=`${header(s)}<main id='main' class='main' tabindex='-1'>${noHead?'':`<div class='page-head'><div><div class='eyebrow'>${s.group==='Operations'?'FLOCKLETTER OPERATIONS':s.group==='Discover'?'FLOCKLETTER':s.group==='Onboarding'?'A GOOD BEGINNING':esc(sampleWorkspace)} / ${s.group.toUpperCase()}</div><h1>${esc(s.title)}</h1><p>${esc(s.description)}</p></div>${primary[s.slug]?go(...primary[s.slug]):''}</div>`}${variants[s.slug]?`<div class='variant-tools' aria-label='Design state examples'><span>Review a state:</span><button class='selected' data-state='default'>Default</button>${variants[s.slug].map(x=>`<button data-state='${esc(x)}'>${x}</button>`).join('')}</div>`:''}<div id='variant-panel'></div><div id='screen-body'>${bodies[s.slug]()}</div><p class='footer'>${s.id} · ${s.group} · Fictional example · <a href='#policies'>Terms & privacy</a> · <a href='#${s.next}'>Continue the walkthrough →</a></p></main><aside class='review-bar' aria-label='Design review navigation'><div><span class='review-label'>DESIGN REVIEW</span><strong>${s.id}</strong><span class='screen-title'> &nbsp;${s.group}</span></div><span class='counter'>${i+1} / ${screens.length}</span><span class='sep'></span><button data-action='catalogue'>All screens</button><button data-action='story'>User story</button><button data-action='previous' aria-label='Previous screen'>←</button><button data-action='next' aria-label='Next screen'>Next →</button></aside>`;document.querySelectorAll('[data-current-plan]').forEach(x=>x.textContent=planNames[plan]);if(sampleCopy)document.querySelectorAll('.email-content>p').forEach(x=>x.textContent=sampleCopy);if(s.slug==='plan-change')document.querySelectorAll('.price-card a[data-plan]').forEach(x=>{x.href='#plan-change';x.textContent='Review this plan';x.removeAttribute('data-plan');x.dataset.action='upgrade'});window.scrollTo(0,0);if(dialog.open)dialog.close()}
function toast(message){const t=document.getElementById('toast');clearTimeout(toastTimer);t.textContent=message;t.classList.add('show');toastTimer=setTimeout(()=>t.classList.remove('show'),5000)}
function modal(title,body){dialog.innerHTML=`<div class='dialog-head'><h2 id='dialog-title'>${title}</h2><button class='btn quiet' data-action='close' aria-label='Close dialog'>✕</button></div><div class='dialog-body'>${body}</div>`;if(!dialog.open)dialog.showModal()}
function catalogue(){const groups=[...new Set(screens.map(s=>s.group))];modal('Explore the complete experience.',`<p class='muted'>54 screens, from first visit to platform operations. Choose a screen or follow a journey.</p><div class='toolbar'>${go('Start a trial','home','quiet')}${go('Prepare a campaign','campaigns','quiet')}${go('Manage the business','billing','quiet')}${go('Be a subscriber','subscribe','quiet')}${go('Run the service','platform','quiet')}</div>${groups.map(g=>`<div class='section-title spaced'><h3>${g}</h3></div><div class='screen-grid'>${screens.filter(s=>s.group===g).map(s=>`<a class='screen-link ${s.id===current.id?'current':''}' href='#${s.slug}'><small>${s.id} · ${s.role}</small>${s.title}</a>`).join('')}</div>`).join('')}`)}
function story(){const s=current;modal(`${s.story} · ${s.goal}`,`<div class='story-box'><div class='eyebrow'>${s.id} · ${s.role.toUpperCase()}</div><h3>What the user wants</h3><p>As a ${s.role.toLowerCase()}, I want to ${s.goal.charAt(0).toLowerCase()+s.goal.slice(1)}, so that I can take the next step with clear information and appropriate control.</p></div><div class='grid cols2'><div class='story-box'><h3>Walk through it</h3><ol>${s.steps.map(x=>`<li>${x}</li>`).join('')}</ol>${go('Continue to the next step →',s.next,'quiet')}</div><div class='story-box'><h3>Expected outcome</h3><p>${s.outcome}</p><h3 class='spaced'>If something goes wrong</h3><p class='spaced'>${s.recovery}</p></div></div><p class='muted'>Requirements: ${s.requirements.join(' · ')}<br>Design criteria only; no real provider behavior is verified.</p>`)}
function state(name){document.querySelectorAll('[data-state]').forEach(b=>b.classList.toggle('selected',b.dataset.state===name));if(name==='default'){render();return}const texts={
'Empty workspace':['A good first step.','Add a brand, verify a sender and invite a permission-based audience.','onboarding'],
'Sending held':['Sending is currently on hold.','Sender review is needed. Editing a draft is separate from send eligibility.','sender-dns'],
'Empty audience':['Your audience starts with an invitation.','Import a list with consent evidence, or share a double opt-in signup form.','signup-form'],
'Empty campaigns':['Your first good letter starts here.','Choose a template. Nothing sends until you review and authorize it.','templates'],
'Read-only':['You have view access.','This proposed analyst view cannot edit, import, change billing or send.','team'],
'Setup failed':['Setup needs another try.','Progress and operation identity are retained. A retry must not create another subscription.','support'],
'Quota exceeded':['This import would exceed your contact allowance.','Reduce eligible sample rows or review an upgrade. Suppressed records are preserved.','plan-change'],
'Verified':['Your sender is verified in this sample.','The next real send would still recheck eligibility. This is not a DNS verification.','onboarding'],
'Blocked':['Three gaps need attention.','Domain verification is missing; the audience exceeds remaining email allowance; a required footer is incomplete. Resolve all three before review.','sender-dns'],
'Paused':['Future submissions are paused.','Accepted messages cannot be recalled. Resume requires another eligibility check.','reports'],
'Uncertain outcome':['Reconciling provider acceptance.','Three recipient outcomes are unknown. Allowance stays reserved. Check authoritative facts before retrying.','support'],
'Seat limit':['Your Tier 2 team is full.','All 3 seats are used. Review an upgrade or an authorized membership change before inviting.','plan-change'],
'Complimentary':['Complimentary customer entitlement.','FFA needs no card, Stripe customer, subscription or paid invoice. Assigned tier is undecided; ordinary sending controls remain.','complimentary'],
'Save failed':['We could not confirm the unsubscribe yet.','Success must wait until suppression is persisted. Keep a safe retry and support path.','support']};const [title,desc,dest]=texts[name]||['Sample state',name,'dashboard'];document.getElementById('variant-panel').innerHTML=note(title,desc,name==='Verified'?'success':'warning')+go('Review next step →',dest,'quiet');if(name.startsWith('Empty')||name==='Complimentary')document.getElementById('screen-body').hidden=true;if(['Read-only','Blocked','Quota exceeded'].includes(name))document.querySelectorAll('#screen-body .btn.primary').forEach(x=>{x.setAttribute('aria-disabled','true');if(x.tagName==='BUTTON')x.disabled=true});if(name==='Blocked')document.getElementById('screen-body').innerHTML=note('Sender not verified','Finish domain verification.','error')+note('Not enough recipient allowance','Reduce the audience or review the plan.','error')+note('Required footer incomplete','Return to the editor before a new review.','error')+go('Repair the campaign','campaign-editor','quiet');if(name==='Save failed')document.getElementById('screen-body').innerHTML=`<section class='recipient'><h1>We could not save that change.</h1><p class='muted spaced'>Your unsubscribe is not yet confirmed.</p>${action('Try the sample again','primary','retry-unsubscribe')}</section>`}
function confirmDialog(title,body,next,label='Confirm sample action'){modal(title,`${note('Design simulation only','Nothing is sent, charged, deleted, connected or provisioned.')}<p>${body}</p><div class='form-actions'>${action('Go back','quiet','close')}<button class='btn primary' data-confirm-route='${next}'>${label}</button></div>`)}
const actions={'import-review':()=>{if(!document.getElementById('import-consent').checked){toast('Confirm permission to contact this audience for the selected brand before continuing.');return}route('import-review')},catalogue,story,close:()=>dialog.close(),previous:()=>route(screens[(screens.indexOf(current)+screens.length-1)%screens.length].slug),next:()=>route(current.next),
demo:()=>toast('Sample action reviewed. No external change occurred.'),saved:()=>toast('Saved in this design example. No account data was changed.'),resend:()=>toast('Sample resend state. No email was sent.'),expired:()=>modal('This invitation or code has expired.',`<p class='muted'>Request a fresh step through the account or invitation flow.</p>${action('Simulate a fresh request','primary','resend')}`),
'email-signup':()=>{sampleAuthNext='workspace-onboarding';route('verify-recover')},'email-signin':()=>{sampleAuthNext='dashboard';route('verify-recover')},
'verify-email':()=>{if(document.querySelector('#screen-body input').value.trim()!=='123456'){toast('For this preview, enter the sample code 123456. No real verification occurs.');return}route(sampleAuthNext)},
checkout:()=>confirmDialog('Stripe-hosted checkout preview',`The future Stripe screen securely collects the card. Review ${planNames[plan]}, 14 days, 250 contacts and 500 total trial emails. This prototype has no payment fields.`,'provisioning','Continue to pending confirmation'),
'provision-failure':()=>state('Setup failed'),'switch-workspace':()=>{sampleWorkspace=sampleWorkspace==='Alpine Paper Co.'?'Juniper Workshop':'Alpine Paper Co.';render();document.getElementById('variant-panel').innerHTML=note('Workspace-switch concept','The header changes here; other sample fixtures remain illustrative. Real data isolation is an implementation requirement.')},
company:()=>modal('Add a company',`${field('Company name','Juniper Workshop LLC')}<p class='muted'>Tier 2 allows 3 companies and 3 brands total. This does not increase mailing allowance.</p>${action('Save sample company','primary','saved')}`),
'dns-ready':()=>state('Verified'),'copy-example':()=>toast('Example instructions reviewed. Use actual provider-issued DNS values later.'),'sample-file':()=>toast('Bundled fictional CSV example selected. No local file was read or uploaded.'),
'import-done':()=>modal('Sample import complete.',`${note('942 new eligible contacts','38 duplicates; 12 invalid rows and 8 suppressed rows excluded.','success')}<p class='muted'>No records were actually imported.</p>${go('Return to audience →','contacts')}`),
'sample-export':()=>modal('Export preview',`<p class='muted'>The future service prepares a scoped export. No customer data is downloaded here.</p><div class='code'>sample_id,status<br>example-001,confirmed<br>example-002,suppressed</div>${action('Close sample','quiet','close')}`),
'sample-link':()=>toast('Sample collection link. No actual product is linked or changed.'),
'editor-block':()=>modal('Edit a sample text block',`<label class='label'>Letter text<textarea id='sample-copy'>${esc(sampleCopy||'A slower moment. A thoughtful note. Meet the paper goods made for both.')}</textarea></label><div class='form-actions'>${action('Cancel','quiet','close')}${action('Apply to sample preview','primary','save-editor')}</div>`),
'save-editor':()=>{sampleCopy=document.getElementById('sample-copy').value;dialog.close();render();toast('Sample preview changed. No campaign was saved to a service.')},
'preview-desktop':()=>{document.getElementById('preview-frame').innerHTML=emailPreview();document.getElementById('preview-frame').style.maxWidth='none'},
'preview-mobile':()=>{document.getElementById('preview-frame').innerHTML=emailPreview();document.getElementById('preview-frame').style.maxWidth='320px';document.getElementById('preview-frame').style.margin='auto'},
'preview-text':()=>{document.getElementById('preview-frame').innerHTML=`<div class='code'>ALPINE PAPER CO.<br><br>A little something for the season ahead<br><br>Good things arrive on paper.<br>A slower moment. A thoughtful note.<br><br>Sample collection link: example.com<br>Preferences · Unsubscribe<br>Sample sender mailing address</div>`},
'preflight-blocked':()=>state('Blocked'),'test-sent':()=>toast('Sample test requested for avery@example.com. Nothing was sent. Real tests use email allowance.'),
'confirm-send':()=>{if(!document.getElementById('review-check').checked){toast('Review the sample inputs before continuing.');return}confirmDialog('Authorize this sample campaign?', 'Review draft 7, Alpine Paper Co., 2,340 eligible recipients and the selected timing. Edited inputs require renewed authorization.','send-progress','Confirm simulated send')},
'pause-send':()=>state('Paused'),'cancel-send':()=>confirmDialog('Cancel future submissions?', 'Already accepted messages cannot be recalled. Only future submissions stop.','reports','Preview canceled-work outcome'),'uncertain':()=>state('Uncertain outcome'),
invite:()=>modal('Invite a teammate',`${note('Tier 2 is full.','3 members are active. No invitation is sent from this prototype.','warning')}${field('Invitee email','new-teammate@example.com','email')}${select('Proposed role',['Editor','Analyst'])}${go('Review Tier 3 →','plan-change')}${go('Inspect invitation design','invitation','link')}`),
permissions:()=>confirmDialog('Review changed capabilities', 'Capabilities narrow an existing Clerk membership. Revoked authority must stop pending work. The final role matrix remains proposed.','team','Confirm sample change'),
'remove-member':()=>confirmDialog('Review membership removal', 'Protect the last owner and revoke membership through Clerk. No real member is removed here.','team','Preview completed removal'),
'clerk-profile':()=>modal('Clerk account management',`<p class='muted'>The real component will manage profile, Google, Apple and Microsoft connections, verified email for one-time codes, recovery and sessions. Account-linking and recovery safeguards remain under review. No actual Clerk connection is used.</p>${field('Sample display name','Avery Morgan')}${action('Close account preview','primary','close')}`),
'revoke-session':()=>confirmDialog('Revoke a sample session?', 'A revoked session would require Clerk sign-in again. Your actual sessions are unchanged.','signin','Preview signed-out state'),
portal:()=>modal('Stripe customer portal preview',`<p class='muted'>Stripe handles payment methods and invoices. Verified provider facts determine access.</p>${go('See confirmation pending','provisioning')}${go('See failed payment','payment-recovery','link')}`),
'complimentary-view':()=>state('Complimentary'),upgrade:()=>confirmDialog('Review a plan change', 'Prices and limits come from the catalogue. Proration and effective-date details remain proposed. Already consumed usage remains counted.','billing','Preview confirmed plan change'),
'cancel-account':()=>confirmDialog('Review cancellation', 'Proposed policy retains access until effective service end and stops renewals. 90-day retention is accepted; its clock and narrow exceptions remain open.','billing','Preview cancellation scheduled'),
'delete-request':()=>modal('Review data deletion',`${note('Policy and authority check required','The final flow verifies the requester and scope and asks for confirmation before deletion.')}<p>No data is deleted. Consider the application, engine, media, exports and restoration behavior.</p>${go('Review support path','support','quiet')}`),
'revoke-grant':()=>confirmDialog('Revoke this sample connection?', 'The future service rejects new commands and unauthorized pending sends. No actual credential is revoked.','integrations','Preview revoked grant'),
'grant-demo':()=>{toast('Sample consent reviewed. No credential or access was created.');route('integrations')},
'support-reply':()=>toast('Sample reply prepared. No email was sent.'),'human-review':()=>toast('Sample escalation recorded. No real request was sent.'),
'subscribe-demo':()=>{if(!document.getElementById('subscribe-consent').checked){toast('Choose whether to receive this brand’s updates before continuing.');return}route('confirmation')},
confirmed:()=>modal('You are on the sample list.',`${note('Confirmation-success design','The real service records confirmation before sending becomes eligible. No address is subscribed here.','success')}${go('Manage preferences →','preferences')}`),
'unsubscribe-failed':()=>state('Save failed'),'retry-unsubscribe':()=>{render();toast('Successful suppression state restored for review. No real preference changed.')},'neutral-resend':()=>toast('If the sample address is eligible, the appropriate next step would arrive. Nothing was sent.'),
'operator-review':()=>toast('Sample diagnostic reason recorded. No support access granted.'),'hold-review':()=>modal('Keep the hold until review is complete.',`<p class='muted'>Approved policy and provider evidence must support a decision. AI cannot remove this hold. Thresholds and release criteria remain open.</p>${action('Keep sample hold','primary','close')}`),
'comp-grant':()=>modal('The complimentary grant remains a draft.',`<p class='muted'>FFA’s assigned tier and grant lifecycle need approval before activation. The eventual record includes workspace, actor, reason, limits and effective dates. It bypasses Stripe and cards.</p>${go('View billing presentation','billing','quiet')}`)
};
document.addEventListener('click',e=>{if(e.target.closest('.skip')){e.preventDefault();document.getElementById('main')?.focus();return}const disabled=e.target.closest(`[aria-disabled='true']`);if(disabled){e.preventDefault();toast('Blocked in this sample review state.');return}const pl=e.target.closest('[data-plan]');if(pl)plan=Number(pl.dataset.plan);const cf=e.target.closest('[data-confirm-route]');if(cf){dialog.close();route(cf.dataset.confirmRoute);return}const st=e.target.closest('[data-state]');if(st){state(st.dataset.state);return}const a=e.target.closest('[data-action]');if(!a)return;e.preventDefault();const key=a.dataset.action;if(key.startsWith('preview-'))a.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===a));if(key==='toggle'){const on=a.getAttribute('aria-checked')==='true';a.setAttribute('aria-checked',String(!on));a.classList.toggle('on',!on);toast('Sample setting changed. Final permissions still apply.');return}if(key==='tab'){a.parentElement.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===a));if(current.slug==='campaigns'){const t=a.textContent;document.querySelectorAll(`[data-table='campaigns'] tbody tr`).forEach(row=>row.hidden=t!=='All campaigns'&&!row.textContent.toLowerCase().includes(t==='Drafts'?'draft':t.toLowerCase()))}else toast('Sample filter selected.');return}if(actions[key])actions[key]();else toast('Sample action reviewed. No external change occurred.')});
document.addEventListener('input',e=>{const type=e.target.dataset.search;if(type){const q=e.target.value.toLowerCase();document.querySelectorAll(`[data-table='${type}'] tbody tr`).forEach(row=>row.hidden=!row.textContent.toLowerCase().includes(q))}});
document.addEventListener('change',e=>{if(e.target.dataset.filter==='status'){const val=e.target.value;document.querySelectorAll(`[data-table='contacts'] tbody tr`).forEach(row=>row.hidden=val!=='All statuses'&&!Array.from(row.querySelectorAll('.badge')).some(x=>x.textContent.trim()===val))}});
document.addEventListener('submit',e=>e.preventDefault());
document.addEventListener('click',e=>{if(e.target.closest(`a[href^='#']`)&&dialog.open)dialog.close()});
window.addEventListener('hashchange',render);render();
